import{_ as e,o as l,c as d,a2 as o}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"ホットキーとマウス操作","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/hotkeys.md","filePath":"ja-JP/user-guide/hotkeys.md","lastUpdated":1788508383000}'),a={name:"ja-JP/user-guide/hotkeys.md"};function r(n,t,s,i,g,c){return l(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="ホットキーとマウス操作" tabindex="-1">ホットキーとマウス操作 <a class="header-anchor" href="#ホットキーとマウス操作" aria-label="Permalink to &quot;ホットキーとマウス操作&quot;">​</a></h1><p>Lertaro はキーボード優先の操作設計を採用しつつ、多彩なマウスジェスチャーと階層型クイックナビゲーションを提供します。固定キーを除き、すべてのグローバルおよびアプリ内ホットキーは <a href="./settings/hotkeys-page.html"><strong>設定 → ホットキー</strong></a> で自由にカスタマイズできます。</p><h2 id="_1-グローバルホットキー一覧" tabindex="-1">1. グローバルホットキー一覧 <a class="header-anchor" href="#_1-グローバルホットキー一覧" aria-label="Permalink to &quot;1. グローバルホットキー一覧&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">機能・アクション</th><th style="text-align:left;">既定のキー</th><th style="text-align:left;">機能説明と操作の詳細</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>クイックウィンドウの表示/非表示</strong></td><td style="text-align:left;"><code>Ctrl</code> の 2 回連打</td><td style="text-align:left;">連打方式または通常の修飾キー組み合わせ（例: <code>Alt+Space</code>、<code>Win+Space</code> など）に変更可能です。<strong>既定でメインウィンドウを開く</strong>を有効にすると、このキーでメインウィンドウを開き、初回表示時は一度だけ前面とフォーカスを処理します。表示中で非アクティブなら再アクティブ化し、すでにアクティブならもう一度押すと閉じます。自動的に最前面へ固定されることはありません。</td></tr><tr><td style="text-align:left;"><strong>クイックジャンプ（Quick Jump）</strong></td><td style="text-align:left;"><code>Ctrl+G</code></td><td style="text-align:left;">ファイルダイアログ内で、直前にファイラーやクイックパネルで開いていたフォルダーへ即座に移動。</td></tr><tr><td style="text-align:left;"><strong>次の項目を選択</strong></td><td style="text-align:left;"><code>Ctrl+N</code> または <code>↓</code></td><td style="text-align:left;">一覧の選択を下に移動。クイックパネルではグループをまたいで連続して移動できます。クイック起動パネルでは方向キーが見た目のグリッドに沿って動き、左右は行の境界を越え、上下は隣接する方向にある同じ列の最も近い項目を探します。グループをまたいで移動することもでき、その方向に同じ列の項目がどこにもない場合だけ現在の位置に留まります。クイック起動パネルが表示され検索語が空の場合、<code>Ctrl+N</code> で次のソースへ循環します。</td></tr><tr><td style="text-align:left;"><strong>前の項目を選択</strong></td><td style="text-align:left;"><code>Ctrl+P</code> または <code>↑</code></td><td style="text-align:left;">一覧の選択を上に移動。クイックパネルでもグループをまたいで連続して移動できます。クイック起動パネルでは方向キーが見た目のグリッドに沿って動き、左右は行の境界を越え、上下は隣接する方向にある同じ列の最も近い項目を探します。グループをまたいで移動することもでき、その方向に同じ列の項目がどこにもない場合だけ現在の位置に留まります。クイック起動パネルが表示され検索語が空の場合、<code>Ctrl+P</code> で前のソースへ循環します。</td></tr><tr><td style="text-align:left;"><strong>1〜9 番目の結果を開く</strong></td><td style="text-align:left;"><code>Ctrl</code> + <code>1</code>〜<code>9</code></td><td style="text-align:left;">修飾キーは変更可能。クイックウィンドウの結果横に数字バッジが表示され、即座に起動可能。</td></tr><tr><td style="text-align:left;"><strong>アクションメニューを開く</strong></td><td style="text-align:left;"><code>Ctrl+O</code> または <code>→</code></td><td style="text-align:left;">選択中の項目のコンテキストアクション（パスのコピー、プロパティ、管理者実行、ファイル操作等）を展開。</td></tr><tr><td style="text-align:left;"><strong>選択項目で検索語を補完</strong></td><td style="text-align:left;"><code>Ctrl+Tab</code></td><td style="text-align:left;">選択項目の名前またはフルパスを検索ボックスに入力し、追加の絞り込みを容易にする。</td></tr><tr><td style="text-align:left;"><strong>QuickLook 即時プレビュー</strong></td><td style="text-align:left;"><code>Alt+P</code></td><td style="text-align:left;">プレビューパネルの開閉（画像、文書、音声・動画の即時再生、フォルダーツリー構造）。</td></tr><tr><td style="text-align:left;"><strong>前の検索履歴語</strong></td><td style="text-align:left;"><code>Alt+Up</code></td><td style="text-align:left;">最近入力した検索キーワードを前に遡って表示。</td></tr><tr><td style="text-align:left;"><strong>次の検索履歴語</strong></td><td style="text-align:left;"><code>Alt+Down</code></td><td style="text-align:left;">最近入力した検索キーワードを後ろに進んで表示。</td></tr><tr><td style="text-align:left;"><strong>現在の履歴語を削除</strong></td><td style="text-align:left;"><code>Ctrl+Delete</code></td><td style="text-align:left;">現在表示されている検索キーワードを検索履歴から削除。</td></tr><tr><td style="text-align:left;"><strong>メインウィンドウを開く</strong></td><td style="text-align:left;"><code>Ctrl+F</code></td><td style="text-align:left;">現在入力中の検索キーワードを引き継いだまま、大画面のメイン検索ウィンドウを開く。</td></tr><tr><td style="text-align:left;"><strong>LocalSend 画面を開く</strong></td><td style="text-align:left;"><code>Ctrl+S</code></td><td style="text-align:left;">LocalSend 経由で他デバイスにファイルやテキストを送信する画面を開く。</td></tr><tr><td style="text-align:left;"><strong>ウィンドウを固定（ピン留め）</strong></td><td style="text-align:left;"><code>Ctrl+T</code></td><td style="text-align:left;">フォーカスを失ってもウィンドウを閉じずに維持（他アプリから文字をコピーして貼り付ける際に便利）。</td></tr><tr><td style="text-align:left;"><strong>クイックパネルの表示/非表示</strong></td><td style="text-align:left;"><code>Ctrl+F2</code></td><td style="text-align:left;">現在のアクティブウィンドウの横に、最近のファイル・お気に入り・ワークスペースを含むパネルを表示。</td></tr></tbody></table><h2 id="_2-検索ボックスのロゴとマウス操作" tabindex="-1">2. 検索ボックスのロゴとマウス操作 <a class="header-anchor" href="#_2-検索ボックスのロゴとマウス操作" aria-label="Permalink to &quot;2. 検索ボックスのロゴとマウス操作&quot;">​</a></h2><p>検索ボックス内の小さなロゴアイコンには、実用的なマウス操作が割り当てられています。</p><h3 id="クイックウィンドウでのロゴ操作" tabindex="-1">クイックウィンドウでのロゴ操作 <a class="header-anchor" href="#クイックウィンドウでのロゴ操作" aria-label="Permalink to &quot;クイックウィンドウでのロゴ操作&quot;">​</a></h3><ul><li><strong>左クリック</strong>：カーソル位置にコンテキストメニューを表示（メインウィンドウの表示、ホットキー切り替え、設定、バージョン情報、クリーン終了、終了）。「メインウィンドウの表示」は現在の検索語を引き継ぎます。</li><li><strong>左ドラッグ</strong>：画面上の検索バーの位置を自由に移動。<strong><code>Ctrl</code> キーを押しながらドラッグ</strong>すると、移動方向が<strong>垂直方向のみ</strong>に固定され、横位置のズレを防げます。</li><li><strong>右クリック</strong>：設定されたサイズを維持したまま、クイックウィンドウを画面中央の既定位置にリセット。</li><li><strong>中クリック</strong>：ウィンドウの「固定（ピン留め）」を切り替え。固定中はロゴが点灯します。</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>クイックウィンドウが記憶する座標は、表示中のモニターに対する<strong>相対比率座標</strong>です。解像度や DPI スケーリングが異なる別のモニターに移動した際も、自動的に画面内に収まるよう比率計算されます。</p></div><h3 id="インラインウィンドウおよびメインウィンドウでのロゴ" tabindex="-1">インラインウィンドウおよびメインウィンドウでのロゴ <a class="header-anchor" href="#インラインウィンドウおよびメインウィンドウでのロゴ" aria-label="Permalink to &quot;インラインウィンドウおよびメインウィンドウでのロゴ&quot;">​</a></h3><ul><li><strong>インラインウィンドウ</strong>：ファイルダイアログ（開く/保存/参照）に埋め込まれている場合、左クリックで <a href="#3-クイックナビゲーションマウス操作"><strong>クイックナビゲーション</strong></a> を表示。通常のエクスプローラーでは装飾表示のみです。</li><li><strong>メインウィンドウ</strong>：ロゴを左クリックするとコンテキストメニューを開きます。すでにメインウィンドウを開いているため、メニューでは<strong>メインウィンドウを表示</strong>は非表示になります。中クリックでウィンドウの固定状態を切り替えます。</li></ul><h2 id="_3-クイックナビゲーション-マウス操作" tabindex="-1">3. クイックナビゲーション（マウス操作） <a class="header-anchor" href="#_3-クイックナビゲーション-マウス操作" aria-label="Permalink to &quot;3. クイックナビゲーション（マウス操作）&quot;">​</a></h2><p>キーボード入力を行わずに、マウス操作だけで頻繁に使うフォルダーや最近のファイルにアクセスできます。</p><h3 id="呼び出し環境" tabindex="-1">呼び出し環境 <a class="header-anchor" href="#呼び出し環境" aria-label="Permalink to &quot;呼び出し環境&quot;">​</a></h3><ul><li><strong>デスクトップの余白</strong>：中クリック（または左ダブルクリック）でメニューを開き、フォルダーやファイルをクリックして直接開く。</li><li><strong>エクスプローラー</strong>：余白部分を中クリックして開き、クリックしたフォルダーへ現在のウィンドウが即座に移動。</li><li><strong>対応ファイラー</strong>：Directory Opus、Total Commander、XYplorer、Files、One Commander などのファイル一覧部分を中クリック（詳細は <a href="./file-manager-support.html"><strong>対応ファイルマネージャー</strong></a> を参照）。</li><li><strong>ファイルダイアログ</strong>：各種アプリの「開く/保存/フォルダーの参照」ダイアログ内で中クリックまたはロゴをクリック。対象フォルダーへ安全に移動します。</li></ul><h3 id="メニュー構成と管理" tabindex="-1">メニュー構成と管理 <a class="header-anchor" href="#メニュー構成と管理" aria-label="Permalink to &quot;メニュー構成と管理&quot;">​</a></h3><p><strong>階層型フォルダーブラウザー（Folder Cascader）</strong> プラグインによって提供されます。</p><ol><li><strong>現在開いているフォルダー</strong>：サポートされているすべてのファイラーで現在開かれているフォルダーを自動集約・重複排除して一覧表示。</li><li><strong>お気に入り・履歴</strong>：スター付きのお気に入りと最近のアクセス履歴を分類表示。</li><li><strong>カスタム階層フォルダー</strong>：<strong>設定 → プラグイン → Folder Cascader</strong> で独自の階層メニューを作成可能（例: <code>仕事/プロジェクトA</code>）。</li><li><strong>クイックフォルダー登録（<code>+</code> ボタン）</strong>：メニューの各階層ヘッダーにある <code>+</code> ボタンをクリックするだけで、現在開いているフォルダーをそのカテゴリに直接追加可能。</li></ol><h2 id="_4-固定キー-変更不可" tabindex="-1">4. 固定キー（変更不可） <a class="header-anchor" href="#_4-固定キー-変更不可" aria-label="Permalink to &quot;4. 固定キー（変更不可）&quot;">​</a></h2><p>直感的な操作の一貫性を保つため、以下のキー操作はすべての設定で固定されています。</p><table tabindex="0"><thead><tr><th style="text-align:left;">キー</th><th style="text-align:left;">状況</th><th style="text-align:left;">動作</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">結果一覧</td><td style="text-align:left;">選択中の項目（ファイル/フォルダー/アプリ/アクション）を開く。</td></tr><tr><td style="text-align:left;"><code>Ctrl+Enter</code></td><td style="text-align:left;">結果一覧</td><td style="text-align:left;">エクスプローラーで選択項目の場所を開いてフォーカス。</td></tr><tr><td style="text-align:left;"><code>Ctrl+Shift+Enter</code></td><td style="text-align:left;">結果一覧</td><td style="text-align:left;">選択した項目を管理者権限で実行。</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">すべて</td><td style="text-align:left;">検索欄に文字があればクリア、空ならウィンドウを閉じるかメニューを終了。</td></tr><tr><td style="text-align:left;"><code>Backspace</code></td><td style="text-align:left;">アクションメニュー</td><td style="text-align:left;">絞り込みテキストが空の状態で押すと、アクションメニューを閉じて結果一覧に戻る。</td></tr><tr><td style="text-align:left;"><code>←</code> / <code>→</code> 方向キー</td><td style="text-align:left;">アクションメニュー</td><td style="text-align:left;">左キーで親メニューに戻り、右キーでサブメニューに入る。</td></tr><tr><td style="text-align:left;"><code>Alt+Space</code></td><td style="text-align:left;">Lertaro の全ウィンドウ</td><td style="text-align:left;">誤動作を防ぐため、システムタイトルバーメニューを無効化。</td></tr><tr><td style="text-align:left;"><code>Alt+F4</code></td><td style="text-align:left;">メイン / 設定ウィンドウ</td><td style="text-align:left;">ウィンドウを閉じる。クイックウィンドウやインライン、プレビューでは無効化。</td></tr></tbody></table><h2 id="_5-プラグインアクションとプロセスブラックリスト" tabindex="-1">5. プラグインアクションとプロセスブラックリスト <a class="header-anchor" href="#_5-プラグインアクションとプロセスブラックリスト" aria-label="Permalink to &quot;5. プラグインアクションとプロセスブラックリスト&quot;">​</a></h2><h3 id="プラグインアクションのホットキー" tabindex="-1">プラグインアクションのホットキー <a class="header-anchor" href="#プラグインアクションのホットキー" aria-label="Permalink to &quot;プラグインアクションのホットキー&quot;">​</a></h3><p>プラグインは固有のアクションショートカットを登録できます（例: パスコピー <code>Ctrl+Shift+C</code>、ファイル切り取り <code>Ctrl+X</code>、コピー <code>Ctrl+C</code>、貼り付け <code>Ctrl+V</code>、削除 <code>Delete</code>、完全削除 <code>Shift+Delete</code> など）。<strong>設定 → ホットキー → プラグインアクション</strong> で確認・変更できます。</p><h3 id="プロセスブラックリストと全画面自動バイパス" tabindex="-1">プロセスブラックリストと全画面自動バイパス <a class="header-anchor" href="#プロセスブラックリストと全画面自動バイパス" aria-label="Permalink to &quot;プロセスブラックリストと全画面自動バイパス&quot;">​</a></h3><ul><li><strong>全画面アプリの自動バイパス</strong>：フルスクリーンで動作する 3D ゲームや動画プレイヤーを検知すると、Lertaro は自動的にすべてのグローバルホットキーを通過させ、ゲームの操作を妨げません。</li><li><strong>カスタムプロセスブラックリスト</strong>：<a href="./settings/hotkeys-page.html#プロセスブラックリスト"><strong>設定 → ホットキー</strong></a> に特定のプロセス名（例: <code>game.exe</code>）を登録すると、そのアプリがフォアグラウンドにある間はホットキーを完全に無効化します。</li></ul>',26)])])}const x=e(a,[["render",r]]);export{h as __pageData,x as default};
